{
  "propositions": [
    {"id": "P1", "text": "O Congresso deve aprovar rapidamente a ratificação da Convenção Interamericana sobre a Proteção dos Direitos Humanos dos Idosos com quórum qualificado."},
    {"id": "P2", "text": "A ratificação da convenção deve ser aprovada antes de outubro para comemorar os 20 anos do Estatuto da Pessoa Idosa."},
    {"id": "P3", "text": "A Convenção Interamericana inova na definição de conceitos como abuso, abandono, maus-tratos, negligência e discriminação contra pessoas idosas."}
  ]
}
